/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    WHSContainerTable   containerTable;

    void printContainerContents(WHSContainerTable _whsContainerTable, NoYesId _showDialog = NoYes::Yes)
    {
        Args            args         = new Args();
        MenuFunction    menuFunction = new MenuFunction(menuitemOutputStr(WHSContainerContents), MenuItemType::Output);

        args.name(ssrsReportStr(WHSContainerContents, Report));
        args.record(_whsContainerTable);
        menuFunction.enumParameter(_showDialog);
        menuFunction.run(args);
    }

    containerTable = WHSContainerTable::findByContainerId('CONV006');

    printContainerContents(containerTable, NoYes::No);
}
